    public boolean connectToSrv() {
        try {
            //System.out.println("Connecting...");
            logger.info("Establishing a connection ");
            server = new Socket(serverName, serverPort);
            msgSender = new ClientMsgSender(server);
            msgSender.start();
            msgReceiver = new ClientMsgReceiver(server, BomberClient.this);
            msgReceiver.start();
            msgSender.sendMsg(new InfoRequestMsg(InfoRequestMsg.GET_SESSION_LIST));
            logger.info("connected to " + serverName);
            return true;
        } catch (IOException e) {
            // TODO Auto-generated catch block
            // e.printStackTrace();
            logger.info("Connection failed");
            return false;
        }
    }
}

/**
 * This class is responsible for sending the messages over the network. When
 * sendMsg() is called a message is appended to the private message queue. This
 * message queue is polled in a looping thread, blocking until a new message
 * becomes available.
 *
 * @author Steffen, Daniel
 * TODO remove "implements Observer and corresponding methods"
 */
public abstract class MsgSender extends Thread implements Observer {

    /**
     * Enqueues a message to be sent over the network.
